1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: grid;
13	    place-items: center;
14	    background: #eef0f3;
15	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
16	  }
17	  .calc {
18	    width: min(320px, 100vw - 32px);
19	    padding: 16px;
20	    border-radius: 20px;
21	    background: #1f2329;
22	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
23	  }
24	  .display {
25	    height: 80px;
26	    margin-bottom: 16px;
27	    padding: 0 12px;
28	    border-radius: 12px;
29	    background: #111418;
30	    color: #fff;
31	    font-size: 40px;
32	    display: flex;
33	    align-items: center;
34	    justify-content: flex-end;
35	    overflow: hidden;
36	    white-space: nowrap;
37	    font-variant-numeric: tabular-nums;
38	  }
39	  .keys {
40	    display: grid;
41	    grid-template-columns: repeat(4, 1fr);
42	    gap: 10px;
43	  }
44	  button {
45	    height: 60px;
46	    border: 0;
47	    border-radius: 12px;
48	    background: #3a4049;
49	    color: #fff;
50	    font: inherit;
51	    font-size: 22px;
52	    cursor: pointer;
53	  }
54	  button:hover { filter: brightness(1.15); }
55	  button:active { filter: brightness(0.9); }
56	  button:focus-visible { outline: 2px solid #8ab4ff; outline-offset: 2px; }
57	  .op { background: #f08c2e; }
58	  .op.active { background: #fff; color: #f08c2e; }
59	  .fn { background: #8a929c; color: #111; }
60	  .wide { grid-column: span 2; }
61	</style>
62	</head>
63	<body>
64	<main class="calc">
65	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" role="status" aria-live="polite">0</div>
66	  <div class="keys">
67	    <button class="fn wide" data-testid="key-clear" data-key="clear">AC</button>
68	    <button class="op" data-testid="key-div" data-key="div" aria-label="divide">÷</button>
69	    <button class="op" data-testid="key-mul" data-key="mul" aria-label="multiply">×</button>
70	    <button data-testid="key-7" data-key="7">7</button>
71	    <button data-testid="key-8" data-key="8">8</button>
72	    <button data-testid="key-9" data-key="9">9</button>
73	    <button class="op" data-testid="key-sub" data-key="sub" aria-label="subtract">−</button>
74	    <button data-testid="key-4" data-key="4">4</button>
75	    <button data-testid="key-5" data-key="5">5</button>
76	    <button data-testid="key-6" data-key="6">6</button>
77	    <button class="op" data-testid="key-add" data-key="add" aria-label="add">+</button>
78	    <button data-testid="key-1" data-key="1">1</button>
79	    <button data-testid="key-2" data-key="2">2</button>
80	    <button data-testid="key-3" data-key="3">3</button>
81	    <button class="op" data-testid="key-equals" data-key="equals" aria-label="equals">=</button>
82	    <button class="wide" data-testid="key-0" data-key="0">0</button>
83	    <button data-testid="key-dot" data-key="dot" aria-label="decimal point">.</button>
84	  </div>
85	</main>
86	<script>
87	// Pure calculator logic. State: acc (stored left operand), op (pending operator),
88	// entry (digits being typed, or null), value (the current number, never rounded),
89	// error (true after a division by zero; only clear leaves it).
90	var OPS = {
91	  add: function (a, b) { return a + b; },
92	  sub: function (a, b) { return a - b; },
93	  mul: function (a, b) { return a * b; },
94	  div: function (a, b) { return a / b; }
95	};
96	
97	function initialState() {
98	  return { acc: null, op: null, entry: null, value: 0, error: false };
99	}
100	
101	function errorState(v) {
102	  return { acc: null, op: null, entry: null, value: v, error: true };
103	}
104	
105	function press(s, key) {
106	  if (key === 'clear') return initialState();
107	
108	  // In the error state every key except clear is ignored.
109	  if (s.error) return s;
110	
111	  if (/^[0-9]$/.test(key)) {
112	    var entry = s.entry === null || s.entry === '0' ? key : s.entry + key;
113	    return { acc: s.acc, op: s.op, entry: entry, value: Number(entry), error: false };
114	  }
115	
116	  if (key === 'dot') {
117	    var e = s.entry === null ? '0' : s.entry;
118	    if (e.indexOf('.') !== -1) return s;
119	    e += '.';
120	    return { acc: s.acc, op: s.op, entry: e, value: Number(e), error: false };
121	  }
122	
123	  if (key in OPS) {
124	    // Operator right after another operator replaces it.
125	    if (s.op && s.entry === null) return { acc: s.acc, op: key, entry: null, value: s.value, error: false };
126	    // Immediate execution: finish the waiting operation first, strictly left to right,
127	    // no precedence. The display always shows a real running result.
128	    var v = s.op ? OPS[s.op](s.acc, s.value) : s.value;
129	    if (!isFinite(v)) return errorState(v);
130	    return { acc: v, op: key, entry: null, value: v, error: false };
131	  }
132	
133	  if (key === 'equals') {
134	    if (!s.op) return { acc: null, op: null, entry: null, value: s.value, error: false };
135	    var r = OPS[s.op](s.acc, s.value);
136	    if (!isFinite(r)) return errorState(r);
137	    return { acc: null, op: null, entry: null, value: r, error: false };
138	  }
139	
140	  return s;
141	}
142	
143	// Presentation only: at most 10 significant digits, no trailing zeros, no separators.
144	// Exponential notation only when the rounded magnitude is >= 1e10 or < 1e-9.
145	function formatNumber(x) {
146	  var m = Math.abs(x).toExponential(9).split('e');
147	  var digits = m[0].replace('.', '');
148	  var exp = Number(m[1]);
149	  var sign = x < 0 ? '-' : '';
150	  if (x !== 0 && (exp >= 10 || exp < -9)) {
151	    return sign + m[0].replace(/\.?0+$/, '') + 'e' + m[1];
152	  }
153	  var int = exp >= 0 ? digits.slice(0, exp + 1) : '0';
154	  var frac = (exp >= 0 ? digits.slice(exp + 1) : '0'.repeat(-exp - 1) + digits).replace(/0+$/, '');
155	  return (int === '0' && frac === '' ? '' : sign) + int + (frac ? '.' + frac : '');
156	}
157	
158	// Visible text: the entry exactly as typed, Error, or the value formatted at render time.
159	function displayText(s) {
160	  if (s.error) return 'Error';
161	  if (s.entry !== null) return s.entry;
162	  return formatNumber(s.value);
163	}
164	
165	if (typeof document !== 'undefined') {
166	  var state = initialState();
167	  var display = document.querySelector('[data-testid="calc-display"]');
168	  var opButtons = document.querySelectorAll('[data-key="add"],[data-key="sub"],[data-key="mul"],[data-key="div"]');
169	
170	  function render() {
171	    display.textContent = displayText(state);
172	    display.setAttribute('data-value', String(state.value));
173	    display.setAttribute('data-error', state.error ? 'true' : 'false');
174	    for (var i = 0; i < opButtons.length; i++) {
175	      var b = opButtons[i];
176	      b.classList.toggle('active', state.op === b.dataset.key && state.entry === null);
177	    }
178	  }
179	
180	  document.querySelector('.keys').addEventListener('click', function (ev) {
181	    var btn = ev.target.closest('button');
182	    if (!btn) return;
183	    state = press(state, btn.dataset.key);
184	    render();
185	  });
186	
187	  var KEYMAP = { '.': 'dot', ',': 'dot', '+': 'add', '-': 'sub', '*': 'mul', 'x': 'mul', '/': 'div',
188	    '=': 'equals', 'Enter': 'equals', 'Escape': 'clear', 'c': 'clear', 'C': 'clear' };
189	  document.addEventListener('keydown', function (ev) {
190	    var key = /^[0-9]$/.test(ev.key) ? ev.key : KEYMAP[ev.key];
191	    if (!key || ev.ctrlKey || ev.metaKey || ev.altKey) return;
192	    ev.preventDefault();
193	    state = press(state, key);
194	    render();
195	  });
196	
197	  render();
198	}
199	</script>
200	</body>
201	</html>
